<?php require '../includes/bootstrap.php';admin_required();if(isset($_POST['confirm'])){$pdo->prepare("UPDATE selections SET status='CONFIRMED' WHERE selection_id=?")->execute([(int)$_POST['confirm']]);flash('success','Selection confirmed.');redirect('selections.php');}$rows=$pdo->query('SELECT s.selection_id,s.status,s.selected_at,st.name,st.application_no,p.problem_code,p.title,e.event_name,t.team_name FROM selections s JOIN students st ON st.student_id=s.student_id JOIN problem_statements p ON p.problem_id=s.problem_id JOIN events e ON e.event_id=p.event_id LEFT JOIN teams t ON t.team_id=s.team_id ORDER BY s.selected_at DESC')->fetchAll();$title='Selections';$base='../';$nav='<a href="dashboard.php">Dashboard</a><a href="events.php">Events</a><a href="problems.php">Problems</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><h1>Selections</h1><div class="card"><table class="table"><tr><th>Student</th><th>Problem</th><th>Event</th><th>Team</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><br><small><?=e($r['application_no'])?></small></td><td><?=e($r['problem_code'])?> · <?=e($r['title'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['team_name']?:'—')?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?php if($r['status']==='SELECTED'):?><form method="post"><button class="btn" name="confirm" value="<?=e($r['selection_id'])?>">Confirm</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php include '../includes/footer.php';?>
